export type ParsedMarkInstruction<
  TProgram extends string = typeof SPAN_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    marker: TAccountMetas[0];
    config: TAccountMetas[1];
    candle: TAccountMetas[2];
    ticket: TAccountMetas[3];
    feed: TAccountMetas[4];
    spanMint: TAccountMetas[5];
    spanHold: TAccountMetas[6];
    spanTokenProgram: TAccountMetas[7];
    eventAuthority: TAccountMetas[8];
    program: TAccountMetas[9];
  };
  data: MarkInstructionData;
};

export function parseMarkInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedMarkInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 10) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 10,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      marker: getNextAccount(),
      config: getNextAccount(),
      candle: getNextAccount(),
      ticket: getNextAccount(),
      feed: getNextAccount(),
      spanMint: getNextAccount(),
      spanHold: getNextAccount(),
      spanTokenProgram: getNextAccount(),
      eventAuthority: getNextAccount(),
      program: getNextAccount(),
    },
    data: getMarkInstructionDataDecoder().decode(instruction.data),
  };
}
